for(genvar ev=0;ev<32;ev=ev+1) begin: g_direct_event_select
  assign release_matches[ev]=ev<=maximum_voice_index && allocated_mask_o[ev] &&
      envelope_state[ev]!=ENVELOPE_RELEASE && envelope_state[ev]!=ENVELOPE_IDLE &&
